        {"question_id": "p01-02-q3", "type": "vocabulary_in_context", "prompt": "As used in the final paragraph, 'found wanting' most nearly means:", "options": [{"id": "A", "text": "Proven to be desired by workers"}, {"id": "B", "text": "Shown to be insufficient or inadequate"}, {"id": "C", "text": "Discovered to be missing entirely"}, {"id": "D", "text": "Confirmed as historically accurate"}, {"id": "E", "text": "Requested by economic historians"}], "correct_option_id": "B", "explanation": "'Found wanting' is an idiom meaning judged to be inadequate or falling short, which fits the sentence's contrast with an argument that has been 'tested' and failed.", "difficulty": "medium"},
        {"question_id": "p01-02-q4", "type": "strengthen_weaken", "prompt": "Which finding, if true, would most weaken the author's central argument?", "options": [{"id": "A", "text": "AI adoption has been slower than initially predicted in most industries."}, {"id": "B", "text": "New, well-paid job categories have emerged at scale across the sectors most exposed to automation within the past decade."}, {"id": "C", "text": "Some workers report feeling anxious about losing their jobs to AI."}, {"id": "D", "text": "Lift operators and switchboard operators no longer exist."}, {"id": "E", "text": "AI performs well on legal document review tasks."}], "correct_option_id": "B", "explanation": "The author proposes exactly this as 'a meaningful test' of the historical-pattern argument. If it turned out to be true, it would support the optimistic view the author is sceptical of, thereby weakening the author's case for uncertainty.", "difficulty": "hard"}
